def mc(lv, s, o, at, ko, gr, tr, gm='', extra=()):
    return {'lv': lv, 's': s, 'o': o, 'at': at, 'ko': ko, 'gr': gr, 'tr': tr, 'gm': gm, 'extra': list(extra)}
def wr(s, blanks, ko, gr, voc, rule=''):
    return {'lv': '서술', 's': s, 'blanks': blanks, 'ko': ko, 'gr': gr, 'voc': voc, 'rule': rule}

